var PROF={ // kg/m stal (orientacyjnie), w,h mm, t mm, typ
'SHS 40x40x3':{w:40,h:40,t:3,kg:3.41,k:'box'},'SHS 50x50x4':{w:50,h:50,t:4,kg:5.64,k:'box'},'SHS 80x80x4':{w:80,h:80,t:4,kg:9.22,k:'box'},
'RHS 60x40x3':{w:60,h:40,t:3,kg:4.35,k:'box'},'RHS 100x50x4':{w:100,h:50,t:4,kg:8.59,k:'box'},
'CHS 33,7x2,6':{w:33.7,h:33.7,t:2.6,kg:2.01,k:'cyl'},'CHS 48,3x3,2':{w:48.3,h:48.3,t:3.2,kg:3.56,k:'cyl'},'CHS 60,3x3,2':{w:60.3,h:60.3,t:3.2,kg:4.51,k:'cyl'},
'L 40x40x4':{w:40,h:40,t:4,kg:2.42,k:'L'},'L 50x50x5':{w:50,h:50,t:5,kg:3.77,k:'L'},
'UPN 100':{w:50,h:100,t:8.5,kg:10.6,k:'box'},'UPN 120':{w:55,h:120,t:9,kg:13.4,k:'box'},
'IPE 100':{w:55,h:100,t:5.7,kg:8.1,k:'box'},'IPE 160':{w:82,h:160,t:7.4,kg:15.8,k:'box'},'HEA 120':{w:120,h:114,t:8,kg:19.9,k:'box'},
'Płaskownik 40x5':{w:40,h:5,t:5,kg:1.57,k:'box'},'Płaskownik 60x8':{w:60,h:8,t:8,kg:3.77,k:'box'}};
var MAT={S235:{n:'S235',f:1,p:135},S355:{n:'S355',f:1,p:135},INOX:{n:'Nierdzewka 1.4301',f:1.01,p:141},ALU:{n:'Aluminium 6060',f:0.344,p:141}};
var TPL={
rama:{n:'Rama',i:'▭',c:1,p:[['L','Długość',1200],['B','Szerokość',600]],x:'cross'},
stol:{n:'Stojak / stół',i:'╥',c:2,p:[['L','Długość',1200],['B','Szerokość',600],['H','Wysokość',800]],x:'cross'},
wspornik:{n:'Wspornik',i:'◹',c:1,p:[['W','Wysięg',500],['H','Wysokość',400]]},
slup:{n:'Słup z płytą podstawy',i:'┴',c:1,p:[['H','Wysokość',2000],['P','Bok płyty podstawy',250]]},
podest:{n:'Podest',i:'▤',c:3,p:[['L','Długość',2000],['B','Szerokość',1000],['H','Wysokość',1000]],x:'cross'},
balustrada:{n:'Balustrada',i:'┬┬',c:2,p:[['L','Długość',3000],['H','Wysokość',1100],['R','Rozstaw słupków',1000]]},
schody:{n:'Schody',i:'⟋',c:3,p:[['H','Wysokość',1000],['L','Długość biegu',1500],['B','Szerokość',800]]},
kratownica:{n:'Kratownica',i:'⩘',c:3,p:[['L','Rozpiętość',4000],['H','Wysokość',500],['N','Liczba przedziałów',6]]},
obudowa:{n:'Obudowa z blachy giętej',i:'▣',c:2,p:[['L','Długość',500],['B','Szerokość',300],['H','Wysokość',300],['T','Grubość blachy',2]],sheet:1},
plyta:{n:'Płyta cięta',i:'▢',c:0,p:[['L','Długość',300],['B','Szerokość',200],['T','Grubość',10]],sheet:1}};
var ADD={plyty:'Płyty / stopki',sruby:'Śruby / otwory',wzm:'Kątowniki / wzmocnienia',zasl:'Zaślepki'};
var S=load();
function load(){var d={table:{B:1000,L:2000,H:900},type:null,mat:null,prof:'SHS 40x40x3',par:{},parts:1,add:{},cross:1,gus:false,joint:'spaw',split:false,wj:'pachwinowa',proc:null,edits:{},deleted:{},mode:null,aMan:null,start:null,extra:[]};
 try{var t=JSON.parse(localStorage.getItem('rama_table'));if(t)d.table=t;}catch(e){} return d;}
function P(k){var t=TPL[S.type];if(!t)return 0;var def=t.p.filter(function(x){return x[0]==k})[0];return S.par[k]!=null?S.par[k]:(def?def[2]:0);}
function sheet(){return S.type&&TPL[S.type].sheet;}
// ---- złożoność
function bbox(){var g=geom();var mn=[1e9,1e9,1e9],mx=[-1e9,-1e9,-1e9];g.nodes.forEach(function(n){for(var i=0;i<3;i++){mn[i]=Math.min(mn[i],n[i]);mx[i]=Math.max(mx[i],n[i]);}});
 g.plates.forEach(function(p){for(var i=0;i<3;i++){mn[i]=Math.min(mn[i],p.c[i]-p.s[i]/2);mx[i]=Math.max(mx[i],p.c[i]+p.s[i]/2);}});(g.shapes||[]).forEach(function(h){h.pts.forEach(function(p){mn[0]=Math.min(mn[0],p[0]);mx[0]=Math.max(mx[0],p[0]);mn[1]=Math.min(mn[1],p[1]);mx[1]=Math.max(mx[1],p[1]);});mn[2]=Math.min(mn[2],0);mx[2]=Math.max(mx[2],h.depth);});return [mx[0]-mn[0],mx[1]-mn[1],mx[2]-mn[2]];}
function exceeds(){var b=bbox(),a=Math.max(b[0],b[2]),c=Math.min(b[0],b[2]),T=S.table;return a>Math.max(T.L,T.B)||c>Math.min(T.L,T.B);}
function score(){if(!TPL[S.type])return {s:0,r:[]};var r=[],s=TPL[S.type].c;r.push('szablon '+TPL[S.type].n+': +'+s);
 if(S.parts>3){s+=2;r.push('części >3: +2');}else if(S.parts>1){s+=1;r.push('części >1: +1');}
 var na=Object.keys(S.add).filter(function(k){return S.add[k]}).length;if(na){s+=na;r.push('dodatki: +'+na);}
 if(S.mat=='INOX'||S.mat=='ALU'){s+=2;r.push('materiał trudniejszy w spawaniu: +2');}
 if(exceeds()){s+=2;r.push('większe niż stół: +2');}return {s:s,r:r,complex:s>=4};}
// ---- geometria (mm; x=długość, y=wysokość, z=szerokość)
function geom(){var N=[],M=[],PL=[],SH=[],pr=S.prof;if(S.src=='foto')fotoGeom(N,M,PL,SH);
 function n(x,y,z){N.push([x,y,z]);return N.length-1;} function m(a,b,nm){M.push({a:a,b:b,p:pr,nm:nm});}
 var L=P('L'),B=P('B'),H=P('H'),c=S.cross,t=S.type;if(t=='custom')t='stol';
 if(t=='rama'||t=='stol'||t=='podest'){var y=(t=='rama')?0:H;var k=(t=='podest')?Math.max(c,Math.round(L/500)-1):c;
  var a=n(0,y,0),b=n(L,y,0),d=n(L,y,B),e=n(0,y,B);m(a,b,'Podłużnica');m(e,d,'Podłużnica');m(a,e,'Poprzeczka');m(b,d,'Poprzeczka');
  for(var i=1;i<=k;i++){var x=L*i/(k+1);m(n(x,y,0),n(x,y,B),'Poprzeczka');}
  if(t!='rama'){[a,b,d,e].forEach(function(q){var f=n(N[q][0],0,N[q][2]);m(f,q,'Noga');}); if(S.add.plyty)[[0,0],[L,0],[L,B],[0,B]].forEach(function(q){PL.push({c:[q[0],-4,q[1]],s:[100,8,100],nm:'Stopka 100x100x8'});});}
  if(t=='podest')PL.push({c:[L/2,H+3,B/2],s:[L,6,B],nm:'Blacha / krata pomostu'});}
 else if(t=='wspornik'){var W=P('W');var a=n(0,0,0),b=n(0,H,0),d=n(W,H,0);m(a,b,'Słupek');m(b,d,'Ramię');m(a,n(W*0.8,H,0),'Zastrzał');PL.push({c:[-5,H/2,0],s:[10,H+100,150],nm:'Blacha czołowa'});}
 else if(t=='slup'){var Pp=P('P');m(n(0,0,0),n(0,H,0),'Słup');PL.push({c:[0,-7.5,0],s:[Pp,15,Pp],nm:'Płyta podstawy '+Pp+'x'+Pp+'x15'});if(S.add.zasl)PL.push({c:[0,H+3,0],s:[PROF[pr].w,6,PROF[pr].h],nm:'Zaślepka'});}
 else if(t=='balustrada'){var R=P('R'),k=Math.max(1,Math.round(L/R)),top=[],mid=[];
  for(var i=0;i<=k;i++){var x=L*i/k,a=n(x,0,0),b=n(x,H,0);top.push(b);mid.push(n(x,H/2,0));m(a,b,'Słupek');}
  for(var i=0;i<k;i++){m(top[i],top[i+1],'Pochwyt');m(mid[i],mid[i+1],'Przeciąg');}}
 else if(t=='schody'){var s1=n(0,0,0),s2=n(L,H,0),s3=n(0,0,B),s4=n(L,H,B);m(s1,s2,'Policzek');m(s3,s4,'Policzek');var ns=Math.max(2,Math.round(H/180));
  for(var i=1;i<=ns;i++){var f=i/(ns+1);PL.push({c:[L*f,H*f,B/2],s:[L/(ns+1)*0.95,5,B-20],nm:'Stopień'});}}
 else if(t=='kratownica'){var k=Math.max(2,Math.round(P('N'))),bot=[],top=[];for(var i=0;i<=k;i++){bot.push(n(L*i/k,0,0));}
  for(var i=0;i<k;i++){top.push(n(L*(i+0.5)/k,H,0));}
  for(var i=0;i<k;i++){m(bot[i],bot[i+1],'Pas dolny');m(bot[i],top[i],'Krzyżulec');m(top[i],bot[i+1],'Krzyżulec');if(i<k-1)m(top[i],top[i+1],'Pas górny');}}
 else if(t=='obudowa'){var T=P('T');PL.push({c:[L/2,T/2,B/2],s:[L,T,B],nm:'Dno (gięte)'});PL.push({c:[L/2,H/2,T/2],s:[L,H,T],nm:'Ścianka (gięta)'});PL.push({c:[L/2,H/2,B-T/2],s:[L,H,T],nm:'Ścianka (gięta)'});
  PL.push({c:[T/2,H/2,B/2],s:[T,H,B],nm:'Ścianka czołowa'});PL.push({c:[L-T/2,H/2,B/2],s:[T,H,B],nm:'Ścianka czołowa'});}
 else if(t=='plyta'){PL.push({c:[P('L')/2,P('T')/2,P('B')/2],s:[P('L'),P('T'),P('B')],nm:'Płyta '+P('L')+'x'+P('B')+'x'+P('T')});}
 S.extra.forEach(function(x){N.push(x.a.slice());N.push(x.b.slice());M.push({a:N.length-2,b:N.length-1,p:x.p,m:x.m,nm:'Pręt dodany'});});
 M.forEach(function(q,i){q.i=i;var e=S.edits[i];if(e){if(e.p)q.p=e.p;if(e.m)q.m=e.m;if(e.len){var A=N[q.a],Bn=N[q.b],d=[Bn[0]-A[0],Bn[1]-A[1],Bn[2]-A[2]],l=Math.hypot(d[0],d[1],d[2]);N.push([A[0]+d[0]/l*e.len,A[1]+d[1]/l*e.len,A[2]+d[2]/l*e.len]);q.b=N.length-1;}}});
 M=M.filter(function(q){return !S.deleted[q.i]});
 if(S.add.wzm&&M.length>1&&!sheet())PL.push({c:N[M[0].a].slice(),s:[80,80,8],nm:'Węzłówka / wzmocnienie'});
 if(S.gus&&!sheet())M.forEach(function(q){});return {nodes:N,members:M,plates:PL,shapes:SH};}
function len(g,q){var A=g.nodes[q.a],B=g.nodes[q.b];return Math.round(Math.hypot(A[0]-B[0],A[1]-B[1],A[2]-B[2]));}
function thick(){if(S.src=='foto'&&S.fgeo!='rama')return S.fT||10;return sheet()?P('T'):PROF[S.prof].t;}
function aSug(){if(S.mode=='reczne'&&S.aMan)return S.aMan;var t=thick();return Math.max(3,Math.round(0.7*t));}
function welds(){var g=geom(),cnt={},W=[];g.members.forEach(function(q){[q.a,q.b].forEach(function(k){var key=g.nodes[k].map(Math.round).join(',');cnt[key]=(cnt[key]||0)+1;});});
 Object.keys(cnt).forEach(function(k){if(cnt[k]>1)W.push({at:k,n:'Węzeł ('+k.replace(/,/g,'; ')+') mm',m:cnt[k]});});
 g.plates.forEach(function(p){if(S.type!='plyta')W.push({at:p.c.join(','),n:p.nm,m:1});});
 if(S.type=='obudowa')W.length=0,W.push({n:'Naroża pionowe obudowy ×4',m:4});return W;}
function sequence(){var W=welds(),o=[],i=0,j=W.length-1,st=['Przygotuj stanowisko: odtłuść, oczyść krawędzie, sprawdź wymiary i przekątne.','Ustaw elementy na stole i dociśnij ściskami; sprawdź prostokątność (przekątne).','Wykonaj sczepy (punkty) we wszystkich węzłach, zanim zaczniesz spawać na długo.','Zmierz ponownie przekątne; popraw, zanim spoiny zablokują kształt.'];
 var alt=[];while(i<=j){alt.push(W[i]);if(i!=j)alt.push(W[j]);i++;j--;}
 alt.forEach(function(w){st.push('Spawaj: '+w.n+' – '+S.wj+', a≈'+aSug()+' mm (orientacyjnie), krótkie odcinki, naprzemiennie po stronach.');});
 st.push('Studź naturalnie (bez wody), sprawdź odkształcenia i wymiary.');st.push('Oczyść spoiny, kontrola wzrokowa (pęknięcia, podtopienia, porowatość).');return st;}
// ---- kroki
function steps(){var a=[];
 a.push({id:'tryb',q:'Jak chcesz stworzyć projekt?',ch:[['pelny','⚡','Pełny automat – jedno zdjęcie<small>Zdjęcie całego rysunku → aplikacja sama robi 3D</small>'],['historia','🕘','Historia projektów<small>Zapisane projekty – otwórz, zmień nazwę, usuń</small>'],['reczne','✎','Stwórz ręcznie<small>Sam układasz i edytujesz pręty</small>'],['auto','⚙','Stwórz automatycznie<small>Typ i wymiary – resztę dobiera aplikacja</small>'],['pol','◐','Stwórz półautomatycznie<small>Prowadzę krok po kroku, Ty zatwierdzasz</small>']],set:'mode'});
 a.push({id:'stol',q:'Wymiary Twojego stołu spawalniczego',f:[['table.L','Długość stołu',],['table.B','Szerokość stołu'],['table.H','Wysokość stołu']]});
 a.push({id:'zrodlo',q:'Skąd bierzemy projekt?',ch:[['szablon','▭','Z szablonu<small>Gotowe typy konstrukcji</small>'],['foto','📷','Ze zdjęcia rysunku<small>Konkretny projekt z papieru</small>']],set:'src'});
 if(S.src=='foto'){a=a.concat(fotoSteps());a.push({id:'model',info:3});if(S.mode=='reczne'){a.push({id:'wj',q:'Spoiny w węzłach – rodzaj',ch:[['pachwinowa','◺','Pachwinowa'],['czołowa','▯▯','Czołowa']],set:'wj'});a.push({id:'proc',q:'Spoiny – metoda',ch:[[135,'MAG','135 MAG'],[141,'TIG','141 TIG'],[111,'MMA','111 elektroda']],set:'proc'});a.push({id:'aman',q:'Grubość spoiny a [mm]',f:[['aMan','a [mm]']]});}a.push({id:'sum',info:4});return a;}
 if(S.mode=='reczne'){a.push({id:'start',q:'Od czego zaczynamy?',ch:[['szkielet','▭','Szkielet z szablonu'],['pusty','+','Pusty stół']],set:'start'});if(S.start=='szkielet')a.push({id:'typ',q:'Jaki szablon?',ch:Object.keys(TPL).map(function(k){return [k,TPL[k].i,TPL[k].n]}),set:'type'});a.push({id:'model',info:3});a.push({id:'wj',q:'Spoiny w węzłach – rodzaj',ch:[['pachwinowa','◺','Pachwinowa'],['czołowa','▯▯','Czołowa']],set:'wj'});a.push({id:'proc',q:'Spoiny – metoda',ch:[[135,'MAG','135 MAG'],[141,'TIG','141 TIG'],[111,'MMA','111 elektroda']],set:'proc'});a.push({id:'aman',q:'Grubość spoiny a [mm]',f:[['aMan','a [mm] – wpisujesz sam']]});a.push({id:'sum',info:4});return a;}
 a.push({id:'typ',q:'Jaki typ konstrukcji?',ch:Object.keys(TPL).map(function(k){return [k,TPL[k].i,TPL[k].n]}),set:'type'});
 if(S.mode=='auto'){if(S.type){var ps=TPL[S.type].p;for(var i=0;i<ps.length;i+=2)a.push({id:'par'+i,q:'Wymiary: '+TPL[S.type].n+' (mm)',f:ps.slice(i,i+2).map(function(p){return ['par.'+p[0],p[1]+(p[0]=='N'?'':' [mm]')]})});}a.push({id:'model',info:3});a.push({id:'sum',info:4});return a;}
 a.push({id:'mat',q:'Materiał',ch:[['S235','S','S235 (stal konstrukcyjna)'],['S355','S+','S355 (wyższa wytrzymałość)'],['INOX','Cr','Nierdzewka 1.4301'],['ALU','Al','Aluminium']],set:'mat'});
 if(!sheet())a.push({id:'prof',q:'Profil główny',ch:Object.keys(PROF).map(function(k){return [k,PROF[k].k=='cyl'?'○':PROF[k].k=='L'?'∟':'□',k+' · '+PROF[k].kg+' kg/m']}),set:'prof',small:1});
 if(S.type){var ps=TPL[S.type].p;for(var i=0;i<ps.length;i+=2)a.push({id:'par'+i,q:'Wymiary: '+TPL[S.type].n+' (mm)',f:ps.slice(i,i+2).map(function(p){return ['par.'+p[0],p[1]+(p[0]=='N'?'':' [mm]')]})});}
 a.push({id:'parts',q:'Z ilu części składa się konstrukcja?',f:[['parts','Liczba części (rysunków)']],hint:'Policz rysunki w stosunku do części.'});
 a.push({id:'add',q:'Dodatki',multi:Object.keys(ADD).concat(Object.keys(S.add).filter(function(k){return !ADD[k]})).map(function(k){return [k,addName(k)]})});
 a.push({id:'score',info:1});
 var sc=score();if(sc.complex){
  if(TPL[S.type]&&TPL[S.type].x)a.push({id:'cross',q:'Ile poprzeczek pośrednich?',ch:[[0,'0','Brak'],[1,'1','1'],[2,'2','2'],[3,'3','3']],set:'cross'});
  if(!sheet())a.push({id:'gus',q:'Węzłówki (blachy wzmacniające) w narożach?',ch:[[true,'◣','Tak'],[false,'–','Nie']],set:'gus'});
  if(!sheet())a.push({id:'joint',q:'Połączenia w węzłach',ch:[['spaw','⚡','Spawane'],['sruby','⊕','Skręcane (śruby)']],set:'joint'});
  if(exceeds())a.push({id:'split',q:'Model nie mieści się na stole. Podzielić na podzespoły?',ch:[[true,'✂','Tak, podzespoły'],[false,'→','Nie, spawam na podłodze/kozłach']],set:'split'});}
 a.push({id:'wj',q:'Rodzaj spoiny',ch:[['pachwinowa','◺','Pachwinowa (najczęstsza)'],['czołowa','▯▯','Czołowa (styk blach)']],set:'wj'});
 a.push({id:'proc',q:'Metoda spawania',ch:[[135,'MAG','135 MAG (drut, gaz)'],[141,'TIG','141 TIG'],[111,'MMA','111 elektroda otulona']],set:'proc',hint:'Sugestia: '+(S.mat?MAT[S.mat].p:135)+(S.mat=='ALU'||S.mat=='INOX'?' – dla nierdzewki i aluminium zwykle TIG.':' – dla stali czarnej najczęściej MAG.')});
 a.push({id:'tips',info:2});a.push({id:'model',info:3});a.push({id:'sum',info:4});return a;}
var hist=[],cur='tryb',other=null;
function addName(k){return ADD[k]||k.replace(/^x:/,'');}
function addProf(n,o){var a=o.k=='box'?2*o.t*(o.w+o.h)-4*o.t*o.t:o.k=='cyl'?Math.PI*(o.w*o.t-o.t*o.t):o.k=='L'?o.t*(o.w+o.h-o.t):o.w*o.h;if(o.k=='cyl')o.h=o.w;if(o.k=='flat'){o.t=o.h;o.k='box';}PROF[n]={w:o.w,h:o.h,t:o.t,k:o.k,kg:o.kg||Math.round(a*7850/1e6*100)/100,est:!o.kg,cust:1};}
function otherForm(s){var f=function(id,l,v,t){return '<label>'+l+'<input id="'+id+'" '+(t?'type="number" ':'')+'value="'+(v==null?'':v)+'"></label>'},h='<h1>Inne – własna wartość</h1><p class="hint">'+(s.q||'')+'</p>';
 if(s.set=='prof')h+=f('on','Nazwa profilu','Profil nietypowy')+'<label>Rodzaj przekroju<select id="ok"><option value="box">Prostokątny zamknięty</option><option value="cyl">Okrągły (rura)</option><option value="flat">Płaski (płaskownik)</option><option value="L">Kątownik</option></select></label>'+f('ow','Szerokość / średnica [mm]',60,1)+f('oh','Wysokość [mm] (dla rury pomijana)',40,1)+f('ot','Grubość ścianki [mm]',3,1)+f('okg','kg/m (puste = z gęstości 7850, orientacyjnie)','',1);
 else if(s.set=='mat')h+=f('on','Nazwa materiału','Materiał nietypowy')+f('od','Gęstość [kg/m³]',7850,1);
 else if(s.set=='type')h+=f('on','Nazwa konstrukcji','Konstrukcja własna')+'<p class="hint">Startuje jako prosta rama prostopadłościenna – resztę dopasujesz w edytorze.</p>';
 else if(s.multi)h+=f('on','Nazwa dodatku','');
 else h+=f('on','Twoja wartość','');
 return h+'<button class="main" id="osave">✓ Zapisz</button>';}
